import './App.css';
import { useState } from 'react'
import { MovieInfo } from './movies'

export default function SearchBar({onSelect}) {
    const [query, setQuery] = useState('');
    const [isNotEmpty, setEmpty] = useState(false);

    function handleChange(change) {
        setQuery(change);
        if (change.length !== 0) {
            setEmpty(true);
        }
        else {
            setEmpty(false);
        }
    }

    return(
    <div className="Search">
        <input type='text' placeholder='Search for a movie...' className='SearchBar' onChange={(x) => handleChange(x.target.value.toLowerCase())}></input>
        <ul className='Results'>
            {MovieInfo.filter(movie => movie.title.toLowerCase().includes(query)).slice(0,5*isNotEmpty).map((movie) => (
                <li key = {movie.id} className='SearchItem' onClick={() => onSelect(movie)}>{movie.title}</li>
            ))}
        </ul>
      </div>
    );
}