import './App.css';
import React, { useState } from 'react'
import SearchBar from './Searchbar';
import MovieList from './MovieList'
import RecommendationList from './RecommendationList';
import { MovieInfo } from './movies';

function App() {

  const [movies,setMovies] = useState([]);
  const [ratings, setRatings] = useState([]);
  const [isEmpty, setEmpty] = useState(true);
  const [recommendations,setRecommendations] = useState([]);
  const [selectMode, setSelectMode] = useState(true);
  const APIURL = 'https://movie-model-v01-e8gna0cad5gzgpdz.centralus-01.azurewebsites.net/'

  function addMovie(movie) {
    if (movies.filter(film => film === movie).length === 0){
      setMovies([...movies, movie]);
      setEmpty(false);
    }
    
  }

  function rateMovie(id, rating) {
    if (ratings.filter(movie => movie.id === id).length === 0) {
      setRatings([...ratings, {'id': id, 'rating':rating}]);
    }
    else {
      const tmpArray = ratings.map(movie => {
        if (movie.id !== id) {
          return movie;
        }
        else {
          return {'id': id,
          'rating': rating,
          };
        }
    })
    setRatings(tmpArray)
  }
    
  }

  function removeMovie(id) {
    setMovies(movies.filter(movie => movie.id !== id));
    setRatings(ratings.filter(movie=> movie.id !== id));
    if (movies.length === 1) {
      setEmpty(true);
    }
  }

  const handleUpload = async (e) => {
    
    if (e.target.files) {
      const file = e.target.files[0];
      console.log('Uploading file...');

      const formData = new FormData();
      formData.append('file', file);
      setSelectMode(false);
      setEmpty(true);

      try {
        // You can write the URL of your server or any other endpoint used for file upload
        const result = await fetch(APIURL.concat('/letterboxd'), {
          method: 'POST',
          body: formData,
        });

        const data = await result.json();
        setRecommendations(MovieInfo.filter(movie => data.data.includes(movie.id)))
        setEmpty(false)

        console.log(data);
      } catch (error) {
        console.error(error);
        setSelectMode(true);
        setEmpty(movies.length===0);
      }
    }
  };

  const handleSubmit = async (e) => {
    
    setSelectMode(false);
    setEmpty(true);
    try {
      // You can write the URL of your server or any other endpoint used for file upload
      const result = await fetch(APIURL.concat('/table'), {
        method: 'POST',
        headers: {
          'Content-Type': 'Application/json'
        },
        body: JSON.stringify(ratings),
      });

      const data = await result.json();
      setRecommendations(MovieInfo.filter(movie => data.data.includes(movie.id)))
      setEmpty(false);

      console.log(data);
    } catch (error) {
      console.error(error);
      setSelectMode(true);
      setEmpty(movies.length===0);
    }
  };

  function handleReset() {
    setMovies([]);
    setRatings([]);
    setRecommendations([]);
    setEmpty(true);
    setSelectMode(true);
  }

  if (selectMode) {
    return (
      <div className="App">
        <div className="Header">
          <h2>What should I watch next?</h2>
          <h3>Select your Letterboxd ratings or search for a movie to start</h3>
        </div>

        <SearchBar onSelect={addMovie}></SearchBar>
        <MovieList list = {movies} rateFunction={rateMovie} removeFunction={removeMovie}></MovieList>
        {!isEmpty && <div className="Submit" onClick={handleSubmit}>
          <h2>Submit</h2>
        </div>}

        {/* Directions for using the tool that disappear when the first movie is selected, and would reappear if all movies were removed from the table*/}
        {isEmpty && <div className="Instructions">
          <h3>Tips:</h3>
          <p>This data is gotten from October 2023, so movies released after aren't avaliable.</p>
          <p>The more movies you rate, the better your recommendations will be, I'd recommend to rate at least a dozen.</p>
          <p>For best results, don't give every movie you select the same rating.</p>
          <p>For submitting your Letterboxd ratings, input the 'ratings.csv' file you get when <a href='https://letterboxd.com/settings/data/'>exporting your Letterboxd data</a>.</p>
          <p>The <a href='https://grouplens.org/datasets/movielens/'>MovieLens dataset</a> was used as the data for making these recommendations.</p>
          <p>To see more of my work, check out my <a href='https://github.com/Matt-J-O'>Github</a></p>
        </div>}
        
        {isEmpty && <div className="Buttons">
          <label for='LetterboxdFile' className='Button'>Use Letterboxd Ratings</label>
          <input style={{'display':'none'}} type='file' id='LetterboxdFile' onChange={handleUpload}></input>
        </div>}
      </div>
  );
  }
  else {
    return (
        <div className="App">
        <div className="Header">
          <h2>Here's what you should watch next!</h2>
        </div>

        {isEmpty && <div className="loader"></div>}

        {/*A version of movielist, but without a lot of the extra functionality (like doing ratings) */}
        <RecommendationList list = {recommendations}></RecommendationList> 

        {/*A button to  */}
        <div className="Submit" onClick={handleReset}>
          <h2>Reset</h2>
        </div>

      </div>
    )
  }
  
}

export default App;
