import './App.css';

export default function RecommendationList({ list }) {
        
    return(
    <table>
        {list.map(movie => (
            <tr key={movie.id}>
                <th className='Poster'><img src={movie.poster} alt="Movie Poster" className='TablePosters'></img></th>
                <th className='Title'>{movie.title}</th>
            </tr>
        ))}
    </table>
    );
}