import './App.css';

export default function MovieList({ list, rateFunction, removeFunction}) {
    
    // Used to index the stars to change their colors because you can't just do a for loop :(
    const numbers = [1,2,3,4,5]

    function starMouseOver(id, position) {
        numbers.slice(0,position).map((star) => (
            document.getElementById(id+'star'+star).classList.add('Checked')
        ))
    }

    function starMouseOut(id, position) {
        numbers.slice(0,position).map((star) => (
            document.getElementById(id+'star'+star).classList.remove('Checked')
        ))
    }

    function starClick(id, position) {
        numbers.slice(0,5).map((star) => (
            document.getElementById(id+'star'+star).classList.remove('Locked')
        ))

        numbers.slice(0,position).map((star) => (
            document.getElementById(id+'star'+star).classList.add('Locked')
        ))

        rateFunction(id, position)
    }

    function removeMouseOver(id) {
        document.getElementById(id).classList.add('RemoveHover')
    }

    function removeMouseOut(id) {
        document.getElementById(id).classList.remove('RemoveHover')
    }

    function removeClick(id) {
        removeFunction(id)
    }

    return(
    <table>
        {list.map(movie => (
            <tr key={movie.id}>
                <th className='Poster'><img src={movie.poster} alt="Movie Poster" className='TablePosters'></img></th>
                <th className='Title'>{movie.title}</th>
                <th className='Rating'>
                    <span className="fa fa-star" id={movie.id+'star1'} onMouseOver={() => starMouseOver(movie.id,1)}
                        onMouseOut={() => starMouseOut(movie.id,1)} onClick={() => starClick(movie.id, 1)}></span>
                    <span className="fa fa-star" id={movie.id+'star2'} onMouseOver={() => starMouseOver(movie.id,2)}
                        onMouseOut={() => starMouseOut(movie.id,2)} onClick={() => starClick(movie.id, 2)}></span>
                    <span className="fa fa-star" id={movie.id+'star3'} onMouseOver={() => starMouseOver(movie.id,3)}
                        onMouseOut={() => starMouseOut(movie.id,3)} onClick={() => starClick(movie.id, 3)}></span>
                    <span className="fa fa-star" id={movie.id+'star4'} onMouseOver={() => starMouseOver(movie.id,4)}
                        onMouseOut={() => starMouseOut(movie.id,4)} onClick={() => starClick(movie.id, 4)}></span>
                    <span className="fa fa-star" id={movie.id+'star5'} onMouseOver={() => starMouseOver(movie.id,5)}
                        onMouseOut={() => starMouseOut(movie.id,5)} onClick={() => starClick(movie.id, 5)}></span>
                </th>
                <th>
                    <span className="fa fa-times" id={movie.id} onMouseOver={() => removeMouseOver(movie.id)}
                        onMouseOut={() => removeMouseOut(movie.id)} onClick={() => removeClick(movie.id)}></span>
                </th>
            </tr>
        ))}
    </table>
    );
}